import { setTimeout as delay } from 'timers/promises';
import { isPidAlive } from '../utils/pid';
import { execFileSync } from 'child_process';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';
import { errnoCode } from '../utils/errnoCode';

interface RuntimeProcess {
  pid: number;
  isOwned: () => Promise<boolean>;
  timeoutMs?: number;
}

const SHUTDOWN_TIMEOUT_MS = 10_000;
const EXIT_POLL_MS = 100;
const FORCED_EXIT_TIMEOUT_MS = 2_000;
const IDENTITY_TIMEOUT_MS = 3_000;

export const runtimeProcessIdentity = (pid: number): string | null => {
  if (!Number.isSafeInteger(pid) || pid <= 0)
    throw new Error('Invalid runtime PID.');
  try {
    const command = process.platform === 'win32' ? 'powershell.exe' : 'ps';
    const args =
      process.platform === 'win32'
        ? [
            '-NoProfile',
            '-NonInteractive',
            '-Command',
            `(Get-Process -Id ${pid}).StartTime.ToUniversalTime().ToString('o')`,
          ]
        : ['-p', String(pid), '-o', 'lstart='];
    const identity = execFileSync(command, args, {
      encoding: 'utf8',
      timeout: IDENTITY_TIMEOUT_MS,
      env: subprocessEnvironment('verifier'),
      stdio: ['ignore', 'pipe', 'pipe'],
    }).trim();
    if (!identity)
      throw new Error(`Could not read the identity of Rivet process ${pid}.`);
    return identity;
  } catch (error) {
    if (!isPidAlive(pid)) return null;
    throw error;
  }
};

export const stopRuntimeProcess = async ({
  pid,
  isOwned,
  timeoutMs = SHUTDOWN_TIMEOUT_MS,
}: RuntimeProcess): Promise<void> => {
  const identity = runtimeProcessIdentity(pid);
  let isVerified = false;
  const waitForExit = async (waitMs: number): Promise<boolean> => {
    const deadline = Date.now() + waitMs;
    while (isPidAlive(pid)) {
      if (Date.now() >= deadline) return false;
      await delay(EXIT_POLL_MS);
    }
    return true;
  };
  const signal = async (value: NodeJS.Signals): Promise<void> => {
    if (!isPidAlive(pid)) return;
    if (pid === process.pid)
      throw new Error(`Cannot verify ownership of Rivet process ${pid}.`);
    if (!isVerified && !(await isOwned())) {
      if (await waitForExit(timeoutMs)) return;
      throw new Error(`Cannot verify ownership of Rivet process ${pid}.`);
    }
    if (identity === null || runtimeProcessIdentity(pid) !== identity) {
      if (await waitForExit(timeoutMs)) return;
      throw new Error(
        `The identity of Rivet process ${pid} changed during shutdown.`,
      );
    }
    isVerified = true;
    try {
      process.kill(pid, value);
    } catch (error) {
      if (errnoCode(error) !== 'ESRCH') throw error;
    }
  };
  await signal('SIGTERM');
  if (await waitForExit(timeoutMs)) return;
  await signal('SIGKILL');
  if (!(await waitForExit(FORCED_EXIT_TIMEOUT_MS)))
    throw new Error(`Rivet process ${pid} did not exit after forced shutdown.`);
};
